  async viewImage(url,fun) {
    var bucketName = "renewalapplicationemis";
    var filename = url;
    let expiry: number = 1800;
    this.uploadService.getUploadedFiles(bucketName, filename, expiry).subscribe(async (result) => {
      if (result) { 
        let imageUrl: any;
        imageUrl = result.url;
       if(fun == 'model'){
        const modal = await this.modalCtrl.create({
          component: ViewImagePage,
          componentProps: { image:  imageUrl },
          cssClass: 'view-image-modal'
        });
        await modal.present();
       }
        else{
        Object.assign(this.details, { imageUrl : result.url });
        }
      }
    });    
  }
  brtestatus(status){
    if(status == '1'){
     this.details[status].brte_status = 'Onhold'
     this.onholdreason = true;
    }
    else if(status == '2'){
      this.details[status].brte_status = 'Verified'
      this.onholdreason = false;
    }
    else if(status == '3'){
      this.details[status].brte_status = 'Rejected'
      this.onholdreason = true;
    }
    else{
      this.details[status].brte_status = 'Unverfied'
      this.onholdreason = false;
    }
  }


